
CREATE TABLE DATA_MCU (id INT AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, no_mcu VARCHAR(50), tgl_mcu DATE, nama VARCHAR(150), tgl_lahir DATE, posisi VARCHAR(100), departemen VARCHAR(100), perusahaan VARCHAR(150), pemeriksaan_laboratorium TEXT, pemeriksaan_non_laboratorium TEXT);

